import sys

def max_distance(N, times, speeds):
    def calculate_segment_distance(t, v):
        # If time is less than 2 seconds, the train cannot accelerate and decelerate properly
        if t < 2:
            return min(v * t, (v ** 2) / 2)

        # Calculate the time to reach maximum speed
        t_accel = v
        t_decel = v

        # If the total time is less than the time to reach max speed and decelerate back to 0
        if t < t_accel + t_decel:
            # Calculate the maximum distance using the available time
            if t <= t_accel:
                # Only accelerating
                return (t ** 2) / 2
            elif t >= t_accel + t_decel:
                # Accelerating, maintaining, and decelerating
                return (v ** 2) / 2 + v * (t - t_accel - t_decel)
            else:
                # Accelerating and decelerating but not maintaining constant speed
                t_maintain = t - t_accel - t_decel
                return (v ** 2) / 2 + v * t_maintain

        # Otherwise, the train can fully accelerate, maintain, and decelerate
        return (v ** 2) / 2 + v * (t - 2 * v)

    total_distance = 0
    for i in range(N):
        total_distance += calculate_segment_distance(times[i], speeds[i])

    return total_distance

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    times = list(map(int, data[1:N+1]))
    speeds = list(map(int, data[N+1:2*N+1]))

    result = max_distance(N, times, speeds)
    print(f"{result:.15f}")

if __name__ == "__main__":
    main()
